#include "sleela_video.h"
#include <stddef.h>
size_t sleela_video_required_plane_count(sleela_video_pixel_format f){switch(f){case SLEELA_VIDEO_PIXFMT_YUV420P:case SLEELA_VIDEO_PIXFMT_YUV422P:case SLEELA_VIDEO_PIXFMT_YUV444P:return 3;case SLEELA_VIDEO_PIXFMT_NV12:case SLEELA_VIDEO_PIXFMT_P010:return 2;case SLEELA_VIDEO_PIXFMT_GRAY8:case SLEELA_VIDEO_PIXFMT_RGB24:case SLEELA_VIDEO_PIXFMT_RGBA32:return 1;default:return 0;}}
int sleela_video_frame_validate(const sleela_video_frame*f,const sleela_video_limits*l){if(!f||!l||!f->width||!f->height||f->width>l->max_width||f->height>l->max_height||f->plane_count>4||f->plane_count!=sleela_video_required_plane_count(f->format)||!f->timebase_num||!f->timebase_den)return 0;size_t total=0;for(uint32_t i=0;i<f->plane_count;i++){if(!f->planes[i]||!f->strides[i]||!f->sizes[i]||f->sizes[i]>l->max_bytes||total>l->max_bytes-f->sizes[i])return 0;total+=f->sizes[i];}return total<=l->max_bytes&&f->plane_count<=l->max_planes;}
const char*sleela_video_pixel_format_name(sleela_video_pixel_format f){static const char*n[]={"GRAY8","RGB24","RGBA32","YUV420P","YUV422P","YUV444P","NV12","P010"};return f>=0&&f<SLEELA_VIDEO_PIXFMT_COUNT?n[f]:"UNKNOWN";}
